function compactReadKey(s){return String(s||'').toLowerCase().replace(/[\s，,。.!！?？:：;；()（）\[\]【】_\-\/\\*★]+/g,'').replace(/杯$/,'').slice(0,48)}
function commonReadFix(s){return String(s||'').replace(/拿[跌佚迭纳钠衲]/g,'拿铁').replace(/拿铁[人本木]杯/g,'拿铁杯').replace(/咖[哗晔啡]/g,'咖啡').replace(/瑰[复夏]/g,'瑰夏').replace(/生[椰揶]/g,'生椰').replace(/美[式戎]/g,'美式').replace(/澳[自白]/g,'澳白')}
