function normalizeProductName(s){return commonReadFix(String(s||'')).replace(/[\u00a0\t]+/g,' ').replace(/^[x×*]\s*\d+\s*/i,'').replace(/[¥￥]\s*\d+(?:\.\d{1,2})?\s*$/,'').replace(/\s*(?:超大杯|大杯|中杯|小杯)\s*$/,'').replace(/\s*\d{2,4}\s*(?:ml|毫升)\s*$/i,'').replace(/\s*(?:去冰|少冰|正常冰|冰|热|温)\s*$/,'').replace(/\s*[x×*]\s*\d+\s*$/i,'').replace(/[（(]?\s*[人]?\s*杯(?:[）)]|$)?\s*$/,'').replace(/[（(][^）)]{0,2}$/,'').replace(/[（(]\s*$/,'').replace(/[★*]+\s*$/,'').replace(/\s{2,}/g,' ').trim()}
