function productKeywordScore(line){let s=String(line||'').trim(),score=0;score+=builtinProductSimilarity(s);if(!s||s.length>42)return -99;if(/(订单|实付|合计|支付|优惠|配送|取餐|门店|地址|手机号|发票|小计|会员|退款|完成|备注|制作|订单号)/i.test(s))score-=8;if(/(咖啡豆|配件|吸管|糖度|浓度|产品身份|小程序|电话|TEL|编号|第\s*\d+\/\d+\s*杯)/i.test(s))score-=8;if(PRODUCT_TYPE_RULES.some(x=>x.re.test(s)))score+=10;if(/咖啡|拿铁|美式|摩卡|卡布|澳白|dirty|espresso|latte|americano|冷萃|手冲|生椰|丝绒|厚乳|瑰夏/i.test(s))score+=5;if(/拿铁|美式|摩卡|卡布|澳白|dirty|espresso|latte|americano|冷萃|手冲|生椰/i.test(s))score+=4;if(/咖啡豆|配件|吸管|标准浓度|不额外加糖/i.test(s))score-=10;if(/\d+\s*(ml|毫升)/i.test(s))score+=1;if(/[¥￥]\s*\d/.test(s))score-=1;if(ORDER_BRANDS.some(x=>x[0].test(s))&&s.length<10)score-=4;return score}
function extractOrderProduct(lines){let xs=[],isGapNoise=v=>{let t=normalizeProductName(v);if(!t)return true;if(/^[0-9Il|一二三四五六七八九十·.,，。*★_\-]{1,4}$/.test(t))return true;return t.length<=2&&productKeywordScore(t)<=0&&!/^(澳白|摩卡|冷萃|手冲)$/.test(t)};for(let i=0;i<lines.length;i++){let a=normalizeProductName(lines[i]);if(a)xs.push({line:a,score:productKeywordScore(a),i});for(let j=i+1;j<lines.length&&j<=i+3;j++){let mids=lines.slice(i+1,j);if(!mids.every(isGapNoise))break;let b=normalizeProductName(String(lines[i]||'')+String(lines[j]||''));if(b&&b.length<=42){let bs=productKeywordScore(b);if(bs>0)xs.push({line:b,score:bs+1.2-(j-i-1)*.15,i:i+(j-i)*.05})}}}xs=xs.filter(x=>x.line).sort((a,b)=>b.score-a.score||a.i-b.i);return xs[0]?.score>0?repairReadProduct(xs[0].line):''}
function extractOrderPrice(lines,text){let candidates=[];for(let line of lines){let strong=/(实付|支付|合计|共计|应付|总计)/.test(line),currency=/[¥￥]/.test(line);for(let m of line.matchAll(/(?:[¥￥]\s*)?(\d{1,3}(?:\.\d{1,2})?)/g)){let v=Number(m[1]);if(v>0&&v<300)candidates.push({v,score:(strong?6:0)+(currency?3:0)})}}candidates.sort((a,b)=>b.score-a.score||a.v-b.v);return candidates[0]?.score>0?candidates[0].v:0}
function extractOrderSize(text){let m=text.match(/(\d{2,4})\s*(?:ml|毫升)/i);if(m){let v=Number(m[1]);if(v>=30&&v<=1000)return v}if(/超大杯/.test(text))return 600;if(/大杯/.test(text))return 450;if(/中杯/.test(text))return 350;if(/小杯/.test(text))return 250;return 0}
function extractOrderDateTime(text){let out={};let dm=text.match(/(20\d{2})[年\-\/.](\d{1,2})[月\-\/.](\d{1,2})/),tm=text.match(/(?:^|\s)([01]?\d|2[0-3])[:：](\d{2})(?:\s|$)/m);if(dm)out.date=`${dm[1]}-${pad(Number(dm[2]))}-${pad(Number(dm[3]))}`;if(tm)out.time=`${pad(Number(tm[1]))}:${tm[2]}`;return out}
function parseOrderText(text){text=String(text||'').replace(/：/g,':');let lines=text.split(/[\r\n]+/).map(x=>x.trim()).filter(Boolean),productName=extractOrderProduct(lines),brand=detectOrderBrand(text),type=canonicalTypeForName(productName||text,'普通黑咖啡'),price=extractOrderPrice(lines,text),size=extractOrderSize(text),temp=/少冰|去冰|冰|冷/.test(text)?'冰':/热|温/.test(text)?'热':'',dt=extractOrderDateTime(text);return {text,lines,productName,type,brand,price,size,temp,...dt}}
function ocrCandidateScore(text){let t=String(text||'').trim();if(!t)return -999;let r=parseOrderText(t),score=0;if(r.productName)score+=120+Math.min(30,productKeywordScore(r.productName)*3);if(r.brand)score+=18;if(r.temp)score+=5;if(r.size)score+=4;if(r.price)score+=3;let useful=(t.match(/拿铁|美式|咖啡|摩卡|澳白|Dirty|dirty|冷萃|手冲|生椰|瑰夏|SOE/gi)||[]).length;score+=useful*12;score+=Math.min(10,t.length/20);return score}
