function expandedRect(rect,px=.12,py=.14){if(!rect)return null;let x=Math.max(0,rect.x-px),y=Math.max(0,rect.y-py),r=Math.min(1,rect.x+rect.w+px),b=Math.min(1,rect.y+rect.h+py);return {x,y,w:r-x,h:b-y}}
function ocrLineCandidates(text){let lines=String(text||'').split(/[\r\n]+/).map(x=>x.trim()).filter(Boolean),out=[];for(let line of lines){let clean=normalizeProductName(line);if(!clean||clean.length<2||clean.length>38)continue;if(/^(?:D?\d{3,}|Hi[,，]?|配件|电话|TEL|自提|外送|第?\d+\/?\d*杯|N[x×]|20\d{2}[-/.]|\d{1,2}:\d{2})/i.test(clean))continue;let sc=productKeywordScore(clean);if(/瑰夏|SOE|花魁|耶加|埃塞/.test(clean))sc+=2;if(/咖啡豆|细吸管|标准浓度|不额外加糖|少冰|去冰/.test(clean))sc-=5;if(sc>0)out.push({line:clean,score:sc})}out.sort((a,b)=>b.score-a.score||a.line.length-b.line.length);let seen=new Set();return out.filter(x=>!seen.has(x.line)&&seen.add(x.line)).slice(0,6)}
