function productFrequency(){let m=new Map();records.forEach(r=>{let name=String(r.productName||'').trim();if(!name)return;let k=[r.brand||'',name].join('|'),x=m.get(k)||{n:0,last:0,r};x.n++;x.last=Math.max(x.last,Number(r.ts)||0);x.r=r;m.set(k,x)});return [...m.values()].sort((a,b)=>b.n-a.n||b.last-a.last)}
function historicalBrandForProduct(name){name=String(name||'').trim();if(!name)return '';let m={};records.forEach(r=>{if(String(r.productName||'').trim()===name&&r.brand)m[r.brand]=(m[r.brand]||0)+1});return Object.entries(m).sort((a,b)=>b[1]-a[1])[0]?.[0]||''}
