function undoLastChange(){try{let u=JSON.parse(localStorage.getItem(UNDOKEY)||'null');if(!u?.action)return notify('没有可以撤销的操作',true);let a=u.action;if(a.kind==='add')records=records.filter(r=>r.id!==a.id);else if(a.kind==='edit'&&a.record){let i=records.findIndex(r=>r.id===a.record.id);if(i>=0)records[i]=a.record;else records.push(a.record)}else if(a.kind==='delete'&&a.record){if(!records.some(r=>r.id===a.record.id))records.push(a.record)}records.sort((a,b)=>b.ts-a.ts);persist();localStorage.removeItem(UNDOKEY);document.querySelector('.undo-bar')?.remove();renderAll();notify('已撤销')}catch(e){notify('这一步暂时无法撤销',true)}}
