function filterRecords(){let q=$('search').value.trim().toLowerCase(),date=$('filterDate').value,now=Date.now(),type=$('advType')?.value||'',brand=($('advBrand')?.value||'').trim().toLowerCase(),temp=$('advTemp')?.value||'',photo=$('advPhoto')?.value||'',scene=$('advScene')?.value||'',minP=Number($('advMinPrice')?.value),maxP=Number($('advMaxPrice')?.value),hasMin=$('advMinPrice')?.value!=='',hasMax=$('advMaxPrice')?.value!=='';return records.filter(r=>{let okRange=recordRange==='all'||(recordRange==='today'&&localKey(new Date(r.ts))===localKey(new Date()))||(recordRange==='7'&&r.ts>=now-7*864e5)||(recordRange==='30'&&r.ts>=now-30*864e5),okDate=!date||localKey(new Date(r.ts))===date,okQ=!q||[r.productName,r.type,r.brand,r.store,r.note,r.temp,r.scene,r.beanOrigin,r.process,r.roast,r.brewRatio].join(' ').toLowerCase().includes(q),okType=!type||r.type===type,okBrand=!brand||String(r.brand||'').toLowerCase().includes(brand),okTemp=!temp||r.temp===temp,hasPhoto=!!(r.photoId||r.photoPreview||r.nativePhotoPath),okPhoto=!photo||(photo==='yes'?hasPhoto:!hasPhoto),okScene=!scene||r.scene===scene,p=Number(r.price)||0,okPrice=(!hasMin||p>=minP)&&(!hasMax||p<=maxP);return okRange&&okDate&&okQ&&okType&&okBrand&&okTemp&&okPhoto&&okScene&&okPrice}).sort((a,b)=>b.ts-a.ts)}
function renderRecords(){let t=$('advType');if(t&&t.options.length===1)Object.keys(CATALOG).forEach(x=>t.add(new Option(x,x)));let rs=filterRecords();$('recordsList').innerHTML=`<div class="row between" style="margin-bottom:4px"><b>${rs.length} 条记录</b><span class="muted">咖啡因 ${Math.round(sum(rs,'caffeine'))} mg · ${money(sum(rs,'price'))}</span></div>${entriesHtml(rs)}`;hydratePhotos($('recordsList'))}
function rankHtml(obj,formatter=x=>x){let arr=Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,5),mx=Math.max(1,...arr.map(x=>x[1]));if(!arr.length)return '<div class="empty">记录多几杯后这里会更有意思</div>';return `<div class="rank">${arr.map(([k,v])=>`<div class="rank-row"><div class="rank-head"><b>${esc(k||'未填写')}</b><span>${formatter(v)}</span></div><div class="rank-track"><i style="width:${v/mx*100}%"></i></div></div>`).join('')}</div>`}

function parseClock(s){let m=String(s||'23:30').match(/^(\d{1,2}):(\d{2})$/);return m?clamp(Number(m[1])||0,0,23)*60+clamp(Number(m[2])||0,0,59):1410}
function clockText(mins){mins=((Math.round(mins)%1440)+1440)%1440;return pad(Math.floor(mins/60))+':'+pad(mins%60)}
function caffeineRemainAt(rs,t,halfLife=settings.caffeineHalfLife||5){let h=Math.max(1.5,Number(halfLife)||5);return rs.reduce((a,r)=>{let dt=(t-r.ts)/3600000;return a+(dt>=0?(Number(r.caffeine)||0)*Math.pow(.5,dt/h):0)},0)}
function metabolismReportHtml(rs,key){
 let date=new Date(key+'T12:00:00'),sleepMin=parseClock(settings.sleepTime),cutoff=Math.max(4,Math.min(12,Number(settings.cutoffHours)||9)),cutoffMin=sleepMin-cutoff*60,half=Math.max(1.5,Math.min(12,Number(settings.caffeineHalfLife)||5));
 let sleep=new Date(date);sleep.setHours(Math.floor(sleepMin/60),sleepMin%60,0,0);if(sleep.getHours()<12)sleep.setDate(sleep.getDate()+1);
 let cutoffDate=new Date(sleep.getTime()-cutoff*3600000),now=new Date(),isToday=key===localKey(now),end=sleep.getTime()+3*3600000,start=Math.min(new Date(key+'T06:00:00').getTime(),rs[0]?.ts||Infinity),plotStart=Number.isFinite(start)?start:new Date(key+'T06:00:00').getTime();
 let step=30*60000,vals=[];for(let t=plotStart;t<=end;t+=step)vals.push([t,caffeineRemainAt(rs,t,half)]);let ymax=Math.max(50,...vals.map(v=>v[1]))*1.12,w=720,h=230,padX=42,padY=24,span=Math.max(1,end-plotStart),x=t=>padX+(t-plotStart)/span*(w-padX*2),y=v=>h-padY-v/ymax*(h-padY*2);let pts=vals.map(v=>`${x(v[0]).toFixed(1)},${y(v[1]).toFixed(1)}`).join(' '),sleepX=x(sleep.getTime()),cutX=x(cutoffDate.getTime()),bed=caffeineRemainAt(rs,sleep.getTime(),half),current=isToday?caffeineRemainAt(rs,now.getTime(),half):null,last=rs.length?new Date(Math.max(...rs.map(r=>r.ts))):null;
 let markers=rs.map(r=>`<circle cx="${x(r.ts).toFixed(1)}" cy="${y(caffeineRemainAt(rs,r.ts,half)).toFixed(1)}" r="4.2"/><text x="${x(r.ts).toFixed(1)}" y="${Math.max(14,y(caffeineRemainAt(rs,r.ts,half))-9).toFixed(1)}" text-anchor="middle">${Math.round(r.caffeine||0)}</text>`).join('');
 return `<div class="section-title">咖啡因代谢 <span>估算报告</span></div><div class="card metabolism-card"><div class="metabolism-summary"><div><span>${isToday?'当前残留':'睡前残留'}</span><b>${Math.round(isToday?current:bed)} mg</b></div><div><span>预计睡前残留</span><b>${Math.round(bed)} mg</b></div><div><span>建议最晚</span><b>${clockText(cutoffMin)}</b></div><div><span>最后一杯</span><b>${last?pad(last.getHours())+':'+pad(last.getMinutes()):'—'}</b></div></div><div class="metabolism-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="咖啡因代谢曲线"><line class="chart-base" x1="${padX}" x2="${w-padX}" y1="${h-padY}" y2="${h-padY}"/><line class="cutoff-line" x1="${cutX}" x2="${cutX}" y1="${padY}" y2="${h-padY}"/><line class="sleep-line" x1="${sleepX}" x2="${sleepX}" y1="${padY}" y2="${h-padY}"/><polyline class="metabolism-line" points="${pts}" fill="none"/><g class="dose-markers">${markers}</g><text class="cutoff-label" x="${cutX+5}" y="18">最晚 ${clockText(cutoffMin)}</text><text class="sleep-label" x="${Math.max(20,sleepX-65)}" y="18">睡眠 ${settings.sleepTime}</text></svg></div><div class="metabolism-note">按 ${half.toFixed(1)} 小时半衰期估算。个体代谢差异很大，这是一条参考曲线。</div></div>`
}
