function sourceLabel(k){return SOURCE_LABELS[k]||''}
function classifyTextSource(text){let s=String(text||'');if(/订单号|订单详情|实付|支付成功|取餐|配送|已完成|下单时间/.test(s))return 'order';if(/收银|小票|应收|实收|合计|找零|税额|发票/.test(s))return 'receipt';let prices=(s.match(/[¥￥]\s*\d+(?:\.\d{1,2})?/g)||[]).length;if(prices>=3&&/(咖啡|拿铁|美式|茶|饮品|菜单)/.test(s))return 'menu';if(/配料|净含量|营养|生产日期|保质期|毫升|ml/i.test(s)&&/(咖啡|coffee|拿铁|latte|美式|americano)/i.test(s))return 'package';return 'label'}
