function makeSourceAttachment(im,file,raw){let d=makePhotoVersions(im,file,raw);return {display:d.display,thumb:d.thumb,preview:d.preview,full:d._fallbackFull||d.display,width:d.width,height:d.height,sourceType:d.sourceType||file?.type||'image/jpeg',qualityMode:'info-source'}}
function sourceSaveControl(kind){if(!['order','receipt','menu'].includes(kind))return '';return `<label class="source-save"><input type="checkbox" ${draftKeepSource?'checked':''} onchange="draftKeepSource=this.checked"> 保留这张${sourceLabel(kind)||'图片'}</label>`}
function smartSummaryHtml(r,kind){let parts=[];if(r.productName)parts.push(`<div><span>饮品</span><b>${esc(r.productName)}</b></div>`);parts.push(`<div><span>类型</span><b>${esc(r.type)}</b></div>`);if(r.brand)parts.push(`<div><span>品牌</span><b>${esc(r.brand)}</b></div>`);if(r.price)parts.push(`<div><span>金额</span><b>${money(r.price)}</b></div>`);return `<div class="order-card"><b>${sourceLabel(kind)||'图片'}内容已填入</b><span>确认一下，也可以继续修改。</span><div class="order-result">${parts.join('')}</div>${sourceSaveControl(kind)}<div class="order-actions"><button onclick="showOrderTextPaste()">调整文字</button><button onclick="$('recognition').classList.remove('show')">收起</button></div></div>`}
