async function hydratePhotos(root=document){let imgs=[...root.querySelectorAll('img[data-photo]')];for(let img of imgs){try{let p=await getPhoto(img.dataset.photo),src=photoThumb(p);if(!src){let r=records.find(x=>x.photoId===img.dataset.photo||x.id===img.dataset.photo);src=nativeFileUrl(r?.nativePhotoPath)||r?.photoPreview||''}if(src)img.src=src;let w=Number(p?.width)||0,h=Number(p?.height)||0;if(w>0&&h>0&&img.classList.contains('thumb')){let max=118,min=58,ratio=w/h;if(ratio>=1){img.style.width=max+'px';img.style.height=Math.max(min,Math.round(max/ratio))+'px'}else{img.style.height=max+'px';img.style.width=Math.max(min,Math.round(max*ratio))+'px'}}if(img.dataset.openPhoto){img.onclick=()=>viewPhoto(img.dataset.openPhoto,img.dataset.caption||'咖啡照片')}}catch(e){let r=records.find(x=>x.photoId===img.dataset.photo||x.id===img.dataset.photo);let src=nativeFileUrl(r?.nativePhotoPath)||r?.photoPreview||'';if(src)img.src=src}}}
let viewerPhotoId='',viewerScale=1;
async function viewInfoSource(id){let r=records.find(x=>x.id===id);if(!r?.sourceId)return notify('没有保留这张信息图片',true);let p='';try{p=await getPhoto(r.sourceId)}catch(e){}let src=photoFullUrl(p)||photoThumb(p)||r.sourcePreview||'';if(!src)return notify('这张信息图片暂时无法读取',true);viewerPhotoId='';viewerScale=1;$('viewerImg').style.transform='scale(1)';$('viewerImg').src=src;$('viewerCaption').textContent=(sourceLabel(r.infoSourceKind)||'信息图片')+' · '+recordDisplayName(r);$('photoViewer').classList.add('show')}
async function viewPhoto(id,caption){let r=records.find(x=>x.photoId===id||x.id===id),p='';try{p=id?await getPhoto(id):''}catch(e){}let original=nativeFileUrl(r?.nativePhotoPath),src=original||photoFullUrl(p)||r?.photoPreview||'';if(!src)return notify('这张照片暂时无法读取',true);viewerPhotoId=id;viewerScale=1;$('viewerImg').style.transform='scale(1)';$('viewerImg').src=src;let q=r?.nativePhotoPath?' · 原图已保留':(p?.qualityMode==='compressed'||p?.qualityMode==='compressed-fallback'?' · 高清压缩版':' · 旧版预览图');$('viewerCaption').textContent=caption+(typeof p==='object'&&p.width?` · ${p.width}×${p.height}`:'')+q;$('photoViewer').classList.add('show')}
function closePhotoViewer(){$('photoViewer').classList.remove('show');$('viewerImg').src='';viewerPhotoId='';if(viewerObjectUrl){URL.revokeObjectURL(viewerObjectUrl);viewerObjectUrl=''}}
function zoomPhoto(delta){viewerScale=clamp(viewerScale+delta,.7,4);$('viewerImg').style.transform=`scale(${viewerScale})`;}
function dataUrlParts(src){let m=String(src||'').match(/^data:([^;]+);base64,(.+)$/i);return m?{mime:m[1],data:m[2]}:null}
function extForMime(m){m=String(m||'').toLowerCase();return m.includes('png')?'png':m.includes('webp')?'webp':m.includes('heic')||m.includes('heif')?'heic':'jpg'}
function nativeImageSave(base64,name,mime){try{prompt('sipsqueak://imagebegin','');let chunk=8192;for(let i=0;i<base64.length;i+=chunk)prompt(`sipsqueak://imagechunk?data=${encodeURIComponent(base64.slice(i,i+chunk))}`,'');prompt(`sipsqueak://imagefinish?name=${encodeURIComponent(name)}&mime=${encodeURIComponent(mime||'image/jpeg')}`,'');return true}catch(e){return false}}
async function saveViewerPhoto(){if(!viewerPhotoId)return;let r=records.find(x=>x.photoId===viewerPhotoId||x.id===viewerPhotoId);if(r?.nativePhotoPath){let mime=r.photoMime||'image/jpeg',name=`Beanster-Sips-${recordDisplayName(r).replace(/[^\w\u4e00-\u9fff-]/g,'_')}-${Date.now()}.${extForMime(mime)}`;notify('请选择原图保存位置');nativeSavePath(r.nativePhotoPath,name,mime);return}let p='';try{p=await getPhoto(viewerPhotoId)}catch(e){}let parts=dataUrlParts(photoLegacyFull(p));if(!parts)return notify('这条记录没有可保存的原图',true);let name=`Beanster-Sips-${recordDisplayName(r).replace(/[^\w\u4e00-\u9fff-]/g,'_')}-${Date.now()}.${extForMime(parts.mime)}`;if(!nativeImageSave(parts.data,name,parts.mime))notify('无法打开系统保存面板',true)}
async function migratePhotoPreviews(){let changed=false;for(let r of records){if(r.photoId&&!r.photoPreview){try{let p=await getPhoto(r.photoId),src=photoThumb(p);if(src){let im=new Image();await new Promise(res=>{im.onload=res;im.onerror=res;im.src=src});if(im.width){let d=makePhotoVersions(im);r.photoPreview=d.preview;changed=true}}}catch(e){}}}if(changed)persist()}

async function migrateLegacyPhotos(){let changed=false;for(let r of records){if(r.photo&&String(r.photo).startsWith('data:image')){r.photoId=r.id||('m'+Date.now()+Math.random());await putPhoto(r.photoId,r.photo);delete r.photo;changed=true}}if(changed)persist()}

